messages.content:
Game **Neon I/O Runner** siap dibangun: endless runner edukasi bertema neon untuk membedakan perangkat input dan output komputer. Saya menambahkan beberapa item tambahan (scanner, webcam, proyektor, headset) agar tiap kategori punya minimal 3 item, dengan monitor sebagai jebakan miskonsepsi.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "neon-io-runner", title: "Neon I/O Runner", seed: "neon-io-01",
  theme: { preset: "neon" },

  learning: {
    subject: "Teknologi Informasi",
    concept: "Membedakan perangkat input dan output komputer",
    objectives: ["Mengelompokkan perangkat komputer berdasarkan fungsinya sebagai input atau output"],
    misconceptions: ["Monitor dianggap perangkat input karena bisa disentuh (layar sentuh)"],
    mode: "category",
    categories: [
      { id: "input",  label: "Input",  color: "#22D3EE" },
      { id: "output", label: "Output", color: "#E040FB" }
    ],
    items: [
      { id: "keyboard",  label: "Keyboard",        category: "input",  explain: "Memasukkan data berupa huruf dan angka ke komputer." },
      { id: "mouse",     label: "Mouse",           category: "input",  explain: "Menggerakkan kursor dan memberi perintah klik ke komputer." },
      { id: "mikrofon",  label: "Mikrofon",        category: "input",  explain: "Menangkap suara sebagai data masukan ke komputer." },
      { id: "scanner",   label: "Scanner",         category: "input",  explain: "Memindai dokumen menjadi data digital masukan." },
      { id: "webcam",    label: "Webcam",          category: "input",  explain: "Menangkap gambar dan video sebagai data masukan." },
      { id: "monitor",   label: "Monitor",         category: "output", explain: "Menampilkan gambar hasil olahan komputer; monitor biasa adalah output." },
      { id: "speaker",   label: "Speaker",         category: "output", explain: "Mengeluarkan suara hasil olahan komputer." },
      { id: "printer",   label: "Printer",         category: "output", explain: "Mencetak hasil olahan komputer ke kertas sebagai keluaran." },
      { id: "proyektor", label: "Proyektor",       category: "output", explain: "Menampilkan gambar komputer ke layar besar sebagai keluaran." },
      { id: "headset",   label: "Headset",         category: "output", explain: "Mengeluarkan suara ke telinga pengguna sebagai keluaran." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "blok-neon", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "pilar-data", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
